struct MenuVTable {
    char padding[0x48];
    short adjustment;
    short padding2;
    void (*Draw)(void *);
};

struct EntryVTable {
    char padding[0x38];
    short adjustment;
    short padding2;
    void (*Draw)(void *);
};

struct FEMenu {
    char padding0[0x60];
    FEMenu *active;
    char padding1[0x10];
    MenuVTable *vtable;

    void Draw()
    {
        vtable->Draw((char *)this + vtable->adjustment);
    }
};

struct FEMenuEntry {
    int entry_num;
    char padding[0x5c];
    EntryVTable *vtable;

    void Draw()
    {
        vtable->Draw((char *)this + vtable->adjustment);
    }
};

struct PanelFile {
    char padding[0x60];
    void Draw(int layer);
};

struct FEEntityManager {
    char padding0[0x1c0];
    bool cam_stopped;
    char padding1[3];
    int cam_stopped_at;
    char padding2[0xc8];
    bool in_flyin;

    bool InFlyin() { return in_flyin; }
    bool OKtoDrawMain() { return cam_stopped && cam_stopped_at == 0; }
};

struct FEManager {
    char padding[0xc];
    FEEntityManager *em;
};

struct MainFrontEnd {
    char padding0[0x4c];
    FEMenuEntry *highlighted;
    char padding1[0x10];
    FEMenu *active;
    char padding2[0x9c];
    PanelFile panel;
    FEManager *manager;
    char padding3[0x130];
    FEMenu *Options;
    FEMenu *Multi;
    FEMenu *Freesurf;
    FEMenu *career_menu;
    FEMenu *multi_sub;

    void Draw();
};

__asm__(".equ Draw__9PanelFilei, 0x001530B8");

void MainFrontEnd::Draw()
{
	if(manager->em->InFlyin() || !manager->em->OKtoDrawMain()) return;
	if(active)
	{
		active->Draw();
		if(active == multi_sub)
			panel.Draw(0);
	}
	else
	{
		panel.Draw(0);
		// draw only highlighted entry
		highlighted->Draw();

		if(highlighted->entry_num == 0)
			Freesurf->Draw();
		else if(highlighted->entry_num == 1)
			career_menu->Draw();
		else if(highlighted->entry_num == 2)
			Multi->Draw();
	}
}
